{
  "Q1": {
    "q1_duty_procs": {
      "verdict": "yes",
      "rationale": "Items 1-3 give Procl. 11046 (2026-14991, 91 FR 46639), 11047 (2026-14992, 91 FR 46653), 11048 (2026-14997, 91 FR 46663), each signed July 20, 2026 and published July 23, 2026."
    },
    "q1_details": {
      "verdict": "yes",
      "rationale": "All ten documents carry the correct FR first page (46639, 46653, 46663, 54789, 58311, 58319, 58325, 58331, 58339, 68861) plus a one-line description that matches what each does (50% duties, 3-day delay, import bans, Part A/B scope changes and section 232 stacking)."
    },
    "q1_delay": {
      "verdict": "yes",
      "rationale": "Item 4: 'Procl. 11056, FR Doc. 2026-17294, 91 FR 54789. Signed Aug 18 ... published Aug 24 ... setting their start at 12:01 a.m. ET, Aug 22, 2026', and it elsewhere states the printed Aug 19 date. fr_doc 2026-17294 confirms signed 2026-08-18, published 2026-08-24."
    },
    "q1_exclusions": {
      "verdict": "yes",
      "rationale": "Items 5-7 list 11061 (2026-18835, 91 FR 58311), 11062 (2026-18836, 91 FR 58319), 11063 (2026-18837, 91 FR 58325), signed Sept 8, published Sept 14, operative from 12:01 a.m. ET Sept 29, 2026, measured against importation."
    },
    "q1_scope": {
      "verdict": "yes",
      "rationale": "Items 8-10 give 11064 (2026-18838) and 11065 (2026-18839), signed Sept 8, applying from 12:01 a.m. Sept 15, 2026, and 11076 (2026-22292), signed Oct 23, filed Oct 29, published Oct 30, applying from 12:01 a.m. Oct 30, 2026."
    },
    "q1_events": {
      "verdict": "yes",
      "rationale": "Each duty/scope entry says 'Measured against: entry for consumption or withdrawal from warehouse for consumption'; the exclusion entries say 'Measured against importation (\"goods imported on or after\")'. Both halves present."
    },
    "q1_dairy_none": {
      "verdict": "yes",
      "rationale": "'Dairy: 11047 (Annex II); 11062 (ban). No dairy scope proclamation has been published', and the alcohol/MV modifications are attributed to 11064, 11065 and 11076. No dairy scope change is attributed to any document."
    },
    "q1_dairy_xref": {
      "verdict": "yes",
      "rationale": "Uncertainty: 'Clause (3) of 11062 refers to a Sept 8, 2026 dairy scope proclamation that does not appear in the Federal Register.'"
    },
    "q1_cite": {
      "verdict": "no",
      "rationale": "Every document carries doc number and FR page, and the basis block cites clauses and pages. No discipline deduction."
    },
    "q1_fab": {
      "verdict": "no",
      "rationale": "The one claim the key does not cover - 11056 'filed Aug 21 at 11:15 a.m.' - is confirmed by fr_grep of 2026-17294 ('[FR Doc. 2026-17294 / Filed 8-21-26; 11:15 am]'). No invented document numbers or quotes found."
    }
  },
  "Q2": {
    "q2a_zero": {
      "verdict": "yes",
      "rationale": "Entry 1 (Aug 20) $0 and entry 2 (11:59 p.m. Aug 21) $0, 'before the operative start'."
    },
    "q2a_third": {
      "verdict": "yes",
      "rationale": "Entry 3: '$40,000 x 50% = $20,000'."
    },
    "q2a_basis": {
      "verdict": "yes",
      "rationale": "Quotes clause (1) of 11056 ('shall be 12:01 a.m. eastern time on August 22, 2026') and cites 91 FR 54790 / FR Doc. 2026-17294."
    },
    "q2b_chapeau": {
      "verdict": "yes",
      "rationale": "'it amends only \"the chapeau of Annex II\" of each proclamation, deleting \"August 19, 2026\" and inserting \"August 22, 2026\"' and '11056 does not amend the numbered clauses (1) and (3) of 11046.' fr_grep of 2026-17294 confirms the chapeau wording and that clauses (1)/(3) were untouched."
    },
    "q2b_resolve": {
      "verdict": "yes",
      "rationale": "Relies on the first sentence of 11056(1) and quotes clause (5) ('inconsistent with this proclamation is superseded to the extent of such inconsistency', 91 FR 54791)."
    },
    "q2c_refund": {
      "verdict": "yes",
      "rationale": "Quotes clause (4) ('refunds shall be processed pursuant to applicable law and CBP's standard procedures') and clause (2) suspend-collection, and notes nothing more specific is given."
    },
    "q2d_no_action": {
      "verdict": "yes",
      "rationale": "'No. 11056 suspended the duties only \"for a period of 3 days\"; the start date was fixed in its operative text', plus the later recital that at 12:01 a.m. Aug 22 'the 3-day suspension ... lapsed, and the additional ad valorem duties ... became effective.'"
    },
    "q2d_reneged": {
      "verdict": "yes",
      "rationale": "Quotes 'On August 21, 2026, Canada reneged on its commitment, ceased negotiating in good faith, and did not remove the discrimination', and the earlier commitment."
    },
    "q2e_thirty": {
      "verdict": "yes",
      "rationale": "Recital 10 of 11046 (30-day rule) plus 'Signed July 20 ... giving 30 days. So Aug 19 is the earliest permissible date.'"
    },
    "q2_cite": {
      "verdict": "no",
      "rationale": "Citations to doc numbers, clauses and pages throughout."
    },
    "q2_fab": {
      "verdict": "no",
      "rationale": "Quotes of 11056(1), (4), (5) and the recitals match the retrieved text; no invented source."
    }
  },
  "Q3": {
    "q3a_shipment_a": {
      "verdict": "yes",
      "rationale": "A: may be imported (arrived before the ban), $15,000."
    },
    "q3a_shipment_b": {
      "verdict": "yes",
      "rationale": "B: imported before Sept 29, quotes clause (2) ('will remain subject to the 50 percent duty rate'), $15,000; not treated as excluded."
    },
    "q3a_shipment_c": {
      "verdict": "yes",
      "rationale": "C: imported 11:30 p.m. Sept 28 before the cutoff, 'the entry on September 29 does not matter for the exclusion', $15,000."
    },
    "q3a_shipment_d": {
      "verdict": "yes",
      "rationale": "D: 'excluded from importation ... No consumption entry may be made, so no section 338 duty arises' (11061(1))."
    },
    "q3b_result": {
      "verdict": "yes",
      "rationale": "E: 'most defensible reading is that clause (2) keeps it under the 50% duty: $15,000 on entry from the zone', with the uncertainty noted."
    },
    "q3b_ftz": {
      "verdict": "yes",
      "rationale": "Cites 11046 clause (4) privileged foreign status ('required admission in privileged foreign status, unless eligible for domestic status') and notes 11061 is silent on FTZs."
    },
    "q3c_invalid": {
      "verdict": "yes",
      "rationale": "Quotes 11061 clause (9)(b) and states $15,000 applies."
    },
    "q3d_no_change": {
      "verdict": "yes",
      "rationale": "'No change. Clause (3) of 11061 ... does not otherwise affect the products ... subject to the additional ad valorem duties.'"
    },
    "q3_cite": {
      "verdict": "no",
      "rationale": "Clause and page cites given for each point."
    },
    "q3_fab": {
      "verdict": "no",
      "rationale": "Quoted language matches 11061 (clauses (1)-(3), (9)(b)) and 11046(4); no invented source."
    }
  },
  "Q4": {
    "q4a_amounts": {
      "verdict": "yes",
      "rationale": "Sept 10: section 232 $25,000 and section 338 $0 on X, Y and Z."
    },
    "q4a_basis": {
      "verdict": "yes",
      "rationale": "Relies on clause (2) of 11046/11047/11048 ('shall not apply to articles subject to duties pursuant to section 232'), not merely on timing."
    },
    "q4b_x": {
      "verdict": "yes",
      "rationale": "X Oct 1: 232 $25,000 + 338 $50,000 = $75,000, citing 11064(1)."
    },
    "q4b_z": {
      "verdict": "yes",
      "rationale": "Z Oct 1: 232 $25,000 + 338 $50,000 = $75,000, citing 11065(1)."
    },
    "q4b_y": {
      "verdict": "yes",
      "rationale": "Y Oct 1: 232 $25,000 + 338 $0 ('no dairy scope proclamation has been published, so clause (2) of 11047 still controls'), with the doubt flagged in Uncertainty."
    },
    "q4c_text": {
      "verdict": "yes",
      "rationale": "Quotes clause (2) of the three duty proclamations and the stacking sentence of 11064(1)/11065(1) with the Sept 15 effective time and FR pages (46641, 46655, 46665, 58332, 58340)."
    },
    "q4c_supersede": {
      "verdict": "yes",
      "rationale": "Cites both pieces with pages and applies the later stacking sentence from Sept 15 (X and Z get $50,000, Y keeps the carve-out), which the criterion accepts."
    },
    "q4c_xref": {
      "verdict": "yes",
      "rationale": "'Clause (3) of 11062 (91 FR 58320) mentions a dairy scope proclamation of Sept 8, 2026; none is in the Federal Register.'"
    },
    "q4c_doubt": {
      "verdict": "yes",
      "rationale": "Uncertainty: 'If the dairy scope proclamation mentioned in 11062 exists but was not published, Y's answer for Oct 1 could differ.'"
    },
    "q4_cite": {
      "verdict": "no",
      "rationale": "Clause and page citations for each result."
    },
    "q4_fab": {
      "verdict": "no",
      "rationale": "Quotations tracked to 11046-11048, 11064 and 11065; nothing invented."
    }
  },
  "Q5": {
    "q5a_p": {
      "verdict": "yes",
      "rationale": "P: No / Yes / Yes / Yes / Yes."
    },
    "q5a_q": {
      "verdict": "yes",
      "rationale": "Q: Yes / No / No / No / No, removed by September Part B from Sept 15."
    },
    "q5a_r": {
      "verdict": "yes",
      "rationale": "R: Yes / Yes / Yes / No / No, because under 11076 'Part A means \"no longer subject\"' from Oct 30."
    },
    "q5a_s": {
      "verdict": "yes",
      "rationale": "S: No / No / No / Yes / Yes via October Part B from 12:01 a.m. Oct 30."
    },
    "q5b_dates": {
      "verdict": "yes",
      "rationale": "Signed Oct 23, 2026; filed Oct 29, 2026 at 11:15 a.m.; published Oct 30, 2026; applies to entries/withdrawals on or after 12:01 a.m. Oct 30, 2026."
    },
    "q5b_prospective": {
      "verdict": "yes",
      "rationale": "'Both scope proclamations ... apply only to entries or withdrawals on or after their stated times. Neither reaches earlier entries. Neither has a refund clause' (contrasting 11056(4))."
    },
    "q5c_days": {
      "verdict": "yes",
      "rationale": "P: Sept 8 to Sept 15 = 7 days; S: Oct 23 to Oct 30 = 7 days."
    },
    "q5c_silent": {
      "verdict": "yes",
      "rationale": "'Neither explains how adding new products within 7 days fits the 30-day rule', then offers the amend/supplement reading expressly as 'an inference'. The quoted recital wording ('earlier than 30 days after the President's proclamation finding') matches 2026-18839 at 91 FR 58340."
    },
    "q5_cite": {
      "verdict": "no",
      "rationale": "Doc numbers, recital numbers and pages throughout."
    },
    "q5_fab": {
      "verdict": "no",
      "rationale": "Recital quote verified in 2026-18839; no invented source."
    }
  },
  "Q6": {
    "q6a_switzerland": {
      "verdict": "yes",
      "rationale": "Switzerland: $8,500 (12.5% - 4%); total $12,500."
    },
    "q6a_norway": {
      "verdict": "yes",
      "rationale": "Norway: flat 12.5% = $12,500; total $16,500."
    },
    "q6a_uk": {
      "verdict": "yes",
      "rationale": "UK: flat 10% = $10,000; total $14,000."
    },
    "q6a_germany": {
      "verdict": "yes",
      "rationale": "Germany: 10% - 4% = 6% = $6,000; total $10,000."
