    "q6a_taiwan": {
      "verdict": "yes",
      "rationale": "Taiwan: $6,000; total $10,000."
    },
    "q6a_turkiye": {
      "verdict": "yes",
      "rationale": "Türkiye: flat 12.5% = $12,500; total $16,500."
    },
    "q6a_japan": {
      "verdict": "yes",
      "rationale": "Japan: $8,500; total $12,500."
    },
    "q6a_liechtenstein": {
      "verdict": "yes",
      "rationale": "Liechtenstein: 'not one of the 60 investigated economies. Section 301 = $0. Total $4,000.'"
    },
    "q6a_hongkong": {
      "verdict": "yes",
      "rationale": "Hong Kong: flat 12.5% = $12,500; total $16,500."
    },
    "q6a_india": {
      "verdict": "yes",
      "rationale": "India: flat 10% = $10,000; total $14,000."
    },
    "q6b_germany12": {
      "verdict": "yes",
      "rationale": "Germany, MFN 12%: $0."
    },
    "q6b_japan12": {
      "verdict": "yes",
      "rationale": "Japan, MFN 12%: 0.5% = $500."
    },
    "q6b_taiwan10": {
      "verdict": "yes",
      "rationale": "Taiwan, MFN exactly 10%: $0."
    },
    "q6b_korea10": {
      "verdict": "yes",
      "rationale": "South Korea, MFN exactly 10%: 2.5% = $2,500."
    },
    "q6b_swiss_free": {
      "verdict": "yes",
      "rationale": "Switzerland, MFN free: $12,500."
    },
    "q6c_net": {
      "verdict": "yes",
      "rationale": "Identifies Switzerland/Japan (12.5% flat -> 12.5% net) and Germany-EU/Taiwan (10% flat -> 10% net) as the changed economies, and expressly says Norway, UK, Türkiye and Hong Kong are unchanged."
    },
    "q6c_india": {
      "verdict": "yes",
      "rationale": "India 12.5% -> 10%, reason 'after the June 5 notice India imposed forced labor import prohibitions', citing the memorandum."
    },
    "q6_cite": {
      "verdict": "no",
      "rationale": "Memorandum, notice and proposal cited with pages throughout."
