    "q6_fab": {
      "verdict": "no",
      "rationale": "Rates and page cites align with the notice/memorandum; no invented source."
    }
  },
  "Q7": {
    "q7a_france": {
      "verdict": "yes",
      "rationale": "$60 duty, 0.5% equivalent, 9.5% rate, $1,140."
    },
    "q7b_italy": {
      "verdict": "yes",
      "rationale": "$1,800 duty payable, 9% equivalent, 1% = $200."
    },
    "q7b_japan": {
      "verdict": "yes",
      "rationale": "12.5% - 9% = 3.5% = $700."
    },
    "q7b_brazil": {
      "verdict": "yes",
      "rationale": "Flat 12.5% = $2,500, noting the equivalent-rate rule does not apply to Brazil."
    },
    "q7c_taiwan": {
      "verdict": "yes",
      "rationale": "11% at or above the 10% cap -> $0."
    },
    "q7c_switzerland": {
      "verdict": "yes",
      "rationale": "12.5% - 11% = 1.5% = $300."
    },
    "q7d_note": {
      "verdict": "yes",
      "rationale": "Identifies U.S. note 52(k) (91 FR 47394) and the divide-by-customs-value formula, and notes note 52(k) states only the below-cap case."
    },
    "q7d_zero": {
      "verdict": "yes",
      "rationale": "Places the zero result in memorandum Sec. 1(a)(ii) (91 FR 47720) and the notice's determinations/'for greater certainty' sentences."
    },
    "q7_cite": {
      "verdict": "no",
      "rationale": "Page cites given for every element."
    },
    "q7_fab": {
      "verdict": "no",
      "rationale": "No invented sources; the page references correspond to the real note 52(k) and determinations."
    }
  },
  "Q8": {
    "q8a_case1": {
      "verdict": "yes",
      "rationale": "Case 1: $10,000, entered after the July 28 cutoff."
    },
    "q8a_case2": {
      "verdict": "yes",
      "rationale": "Case 2: $0."
    },
    "q8a_case3": {
      "verdict": "yes",
      "rationale": "Case 3: $10,000, 12:01 a.m. July 28 is not 'before'."
    },
    "q8a_case4": {
      "verdict": "yes",
      "rationale": "Case 4: $10,000, loaded 6:00 a.m. July 24."
    },
    "q8a_case5": {
      "verdict": "yes",
      "rationale": "Case 5: $0."
    },
    "q8a_case6": {
      "verdict": "yes",
      "rationale": "Case 6: $10,000, withdrawal after July 24 and not in transit."
    },
    "q8a_case7": {
      "verdict": "yes",
      "rationale": "Case 7: $10,000 on the text because the exception covers goods 'loaded onto a vessel'."
    },
    "q8b_where": {
      "verdict": "yes",
      "rationale": "Places the rule only in the DATES line (2026-15181, 91 FR 47318) and says it is not in note 52 or the memorandum."
    },
    "q8c_dates": {
      "verdict": "yes",
      "rationale": "Signed July 23, 2026; duties from 12:01 a.m. ET July 24, 2026; published July 28, 2026."
    },
    "q8d_july30": {
      "verdict": "yes",
      "rationale": "July 30: $10,000, because the note 52(f)(8) exemption applies only from July 31."
    },
    "q8d_aug3": {
      "verdict": "yes",
      "rationale": "Aug 3: $0 under note 52(f)(8)."
    },
    "q8_cite": {
      "verdict": "no",
      "rationale": "DATES line, determinations and Annex I.B all cited with pages."
    },
    "q8_fab": {
      "verdict": "no",
      "rationale": "No invented sources or quotes."
    }
  },
  "Q9": {
    "q9a_assembly": {
      "verdict": "yes",
      "rationale": "$65,000 base x 12.5% = $8,125 under note 52(a)."
    },
    "q9b_repairs": {
      "verdict": "yes",
      "rationale": "$6,000 x 12.5% = $750."
    },
    "q9c_usmca": {
      "verdict": "yes",
      "rationale": "(c)(i) $0 under note 52(h)."
    },
    "q9c_no_claim": {
      "verdict": "yes",
      "rationale": "(c)(ii) 10% x $50,000 = $5,000."
    },
    "q9d_car": {
      "verdict": "yes",
      "rationale": "$0 under note 52(f)(2) for heading 9903.94.01."
    },
    "q9e_reading": {
      "verdict": "yes",
      "rationale": "Concludes the 12.5% duty ($12,500) applies because note 52(f) 'exempts only the section 232 headings it lists' and note 52(a) stacks other chapter 99 duties."
    },
    "q9e_flag": {
      "verdict": "no",
      "rationale": "The (e) answer presents $12,500 as settled and offers no caveat about the proposal's/notice's general treatment of section 232 goods or about headings the note does not list; the Q9 uncertainty field addresses only image-only Annex II lists and paragraph (b). The criterion excludes an image-only caveat and requires the caveat to attach to (e)."
    },
    "q9f_232": {
      "verdict": "yes",
      "rationale": "Proposal would exempt 'all articles and parts currently subject to section 232 tariffs'; adopted note 52(f) is a closed list of headings (metals 9903.82.02/.04-.26, autos, wood, MD/HD vehicles, semiconductors, pharma from July 31)."
    },
    "q9f_info": {
      "verdict": "yes",
      "rationale": "Proposal listed informational materials, donations and accompanied baggage; 'the readable adopted text does not mention them', noting they might sit in an image-only list."
    },
    "q9_cite": {
      "verdict": "no",
      "rationale": "Note subdivisions and pages cited throughout."
    },
    "q9_fab": {
      "verdict": "no",
      "rationale": "No invented sources; quotations align with note 52 and the proposal."
    }
  },
  "Q10": {
    "q10a_338": {
      "verdict": "yes",
      "rationale": "(a) Sept 10: section 338 $0 under 11048 clause (2)."
    },
    "q10a_301": {
